                    <Icon className={`w-5 h-5 ${isActive ? 'text-indigo-400' : 'group-hover:text-slate-100'}`} />
                    <span className="font-medium">{item.label}</span>
                  </div>
                  {isActive && <ChevronRight className="w-4 h-4" />}
                </button>
