import React from 'react';

export const Card: React.FC<{ children: React.ReactNode; className?: string }> = ({ children, className = "" }) => (
  <div className={`bg-slate-900 border border-slate-800 rounded-2xl p-6 shadow-sm ${className}`}>
    {children}
  </div>
);

export const Button: React.FC<{ 
  children: React.ReactNode; 
  onClick?: () => void; 
  type?: 'button' | 'submit';
  variant?: 'primary' | 'secondary' | 'danger' | 'ghost';
  isLoading?: boolean;
  className?: string;
  disabled?: boolean;
}> = ({ children, onClick, type = 'button', variant = 'primary', isLoading, className = "", disabled }) => {
  const variants = {
    primary: "bg-indigo-600 hover:bg-indigo-700 text-white shadow-lg shadow-indigo-600/20",
    secondary: "bg-slate-800 hover:bg-slate-700 text-slate-100 border border-slate-700",
    danger: "bg-red-600/10 hover:bg-red-600/20 text-red-500 border border-red-500/20",
    ghost: "bg-transparent hover:bg-slate-800 text-slate-400 hover:text-slate-100"
  };

  return (
    <button 
      type={type}
      onClick={onClick}
      disabled={isLoading || disabled}
      className={`px-4 py-2.5 rounded-xl font-medium flex items-center justify-center gap-2 transition-all active:scale-95 disabled:opacity-50 disabled:active:scale-100 ${variants[variant]} ${className}`}
    >
      {isLoading ? (
        <div className="w-5 h-5 border-2 border-current border-t-transparent rounded-full animate-spin" />
      ) : children}
    </button>
  );
};

export const Input: React.FC<{
  label?: string;
  type?: string;
  value: string | number;
  onChange: (e: React.ChangeEvent<HTMLInputElement>) => void;
  placeholder?: string;
  required?: boolean;
  className?: string;
  step?: string;
}> = ({ label, type = 'text', value, onChange, placeholder, required, className = "", step }) => (
  <div className={`flex flex-col gap-1.5 ${className}`}>
    {label && <label className="text-sm font-medium text-slate-400 px-1">{label}</label>}
    <input
      type={type}
      value={value}
      onChange={onChange}
      placeholder={placeholder}
      required={required}
      step={step}
      className="bg-slate-800 border border-slate-700 rounded-xl px-4 py-2.5 text-slate-100 focus:outline-none focus:ring-2 focus:ring-indigo-500/50 focus:border-indigo-500 transition-all placeholder:text-slate-600"
    />
  </div>
);

export const Select: React.FC<{
  label?: string;
  value: string;
  onChange: (e: React.ChangeEvent<HTMLSelectElement>) => void;
  options: { value: string; label: string }[];
  placeholder?: string;
  className?: string;
}> = ({ label, value, onChange, options, placeholder, className = "" }) => (
  <div className={`flex flex-col gap-1.5 ${className}`}>
    {label && <label className="text-sm font-medium text-slate-400 px-1">{label}</label>}
    <select
      value={value}
      onChange={onChange}
      className="bg-slate-800 border border-slate-700 rounded-xl px-4 py-2.5 text-slate-100 focus:outline-none focus:ring-2 focus:ring-indigo-500/50 focus:border-indigo-500 transition-all appearance-none cursor-pointer"
    >
      <option value="" disabled>{placeholder || 'Selecione...'}</option>
      {options.map(opt => (
        <option key={opt.value} value={opt.value} className="bg-slate-900">{opt.label}</option>
      ))}
    </select>
  </div>
);

export const Modal: React.FC<{
  isOpen: boolean;
  onClose: () => void;
  title: string;
  children: React.ReactNode;
}> = ({ isOpen, onClose, title, children }) => {
  if (!isOpen) return null;
  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
      <div className="fixed inset-0 bg-black/70 backdrop-blur-md" onClick={onClose} />
      <div className="bg-slate-900 border border-slate-800 rounded-3xl w-full max-w-2xl shadow-2xl relative z-10 flex flex-col max-h-[90vh]">
        <div className="p-6 border-b border-slate-800 flex justify-between items-center">
          <h3 className="text-xl font-bold text-white">{title}</h3>
          <button onClick={onClose} className="p-2 text-slate-400 hover:text-white rounded-full hover:bg-slate-800">
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg>
          </button>
        </div>
        <div className="p-6 overflow-y-auto flex-1">
          {children}
        </div>
      </div>
    </div>
  );
};

export const Badge: React.FC<{ children: React.ReactNode; variant?: 'success' | 'warning' | 'info' }> = ({ children, variant = 'info' }) => {
  const styles = {
    success: 'bg-emerald-500/10 text-emerald-400 border-emerald-500/20',
    warning: 'bg-amber-500/10 text-amber-400 border-amber-500/20',
    info: 'bg-indigo-500/10 text-indigo-400 border-indigo-500/20'
  };
  return (
    <span className={`px-2 py-0.5 rounded-full text-[10px] uppercase font-bold tracking-wider border ${styles[variant]}`}>
      {children}
    </span>
  );
};

import React, { useEffect, useState } from 'react';
import { api } from '../services/api';
import { Employee, MonthlyLaunch } from '../services/types';
import { Card, Badge, Button } from '../components/UI';
import { Users, DollarSign, Receipt, TrendingUp, Download } from 'lucide-react';
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer,
  Cell
} from 'recharts';

const Dashboard: React.FC = () => {
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [launches, setLaunches] = useState<MonthlyLaunch[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [empData, launchData] = await Promise.all([
          api.getEmployees(),
          api.getLaunches()
        ]);
        setEmployees(empData);
        setLaunches(launchData);
      } catch (error) {
        console.error("Error fetching dashboard data", error);
      } finally {
        setLoading(false);
      }
    };
    fetchData();
  }, []);

  const totalPayroll = launches.reduce((acc, curr) => acc + curr.netSalary, 0);
  const avgSalary = employees.length > 0 ? employees.reduce((acc, curr) => acc + curr.baseSalary, 0) / employees.length : 0;

  // Data for chart: Last 5 launches
  const chartData = launches.slice(0, 6).reverse().map(l => ({
    name: l.employeeName.split(' ')[0],
    val: l.netSalary
  }));

  const exportToExcel = () => {
    if (launches.length === 0) return alert("Sem dados para exportar");

    const headers = ["ID", "Funcionário", "Data Fechamento", "Salário Base", "Bônus", "Outros", "Descontos", "Líquido"];
    const rows = launches.map(l => [
      l.id,
      l.employeeName,
      l.closingDate,
      l.baseSalary,
      l.functionBonus,
      l.otherEarnings,
      l.totalDeductions,
      l.netSalary
    ]);

    const csvContent = [headers, ...rows].map(e => e.join(",")).join("\n");
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", `folha_pagamento_${new Date().toISOString().split('T')[0]}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  if (loading) {
    return (
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 animate-pulse">
        {[1,2,3,4].map(i => (
          <div key={i} className="h-32 bg-slate-900 rounded-2xl border border-slate-800" />
        ))}
      </div>
    );
  }

  const kpis = [
    { label: 'Funcionários', value: employees.length, icon: Users, color: 'text-blue-400', bg: 'bg-blue-400/10' },
    { label: 'Total Folha (Líquido)', value: `R$ ${totalPayroll.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}`, icon: DollarSign, color: 'text-emerald-400', bg: 'bg-emerald-400/10' },
    { label: 'Salário Médio', value: `R$ ${avgSalary.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}`, icon: TrendingUp, color: 'text-indigo-400', bg: 'bg-indigo-400/10' },
    { label: 'Lançamentos', value: launches.length, icon: Receipt, color: 'text-amber-400', bg: 'bg-amber-400/10' },
  ];

  return (
    <div className="space-y-8">
      <div>
        <h1 className="text-3xl font-bold text-white mb-2">Visão Geral</h1>
        <p className="text-slate-400">Bem-vindo ao centro de controle de Recursos Humanos.</p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        {kpis.map((kpi, idx) => (
          <Card key={idx} className="flex flex-col gap-4 group transition-all hover:border-slate-700">
            <div className="flex items-center justify-between">
              <div className={`p-3 rounded-xl ${kpi.bg}`}>
                <kpi.icon className={`w-6 h-6 ${kpi.color}`} />
              </div>
              <Badge variant="info">Recente</Badge>
            </div>
            <div>
              <p className="text-sm text-slate-400 font-medium">{kpi.label}</p>
              <h3 className="text-2xl font-bold text-white mt-1">{kpi.value}</h3>
            </div>
          </Card>
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <Card className="lg:col-span-2">
          <div className="flex items-center justify-between mb-8">
            <h3 className="text-lg font-bold text-white">Últimos Pagamentos Líquidos</h3>
            <Button variant="secondary" onClick={exportToExcel} className="text-xs">
              <Download className="w-4 h-4" />
              Exportar CSV
            </Button>
          </div>
          <div className="h-[300px] w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={chartData}>
                <CartesianGrid strokeDasharray="3 3" stroke="#1e293b" vertical={false} />
                <XAxis dataKey="name" stroke="#94a3b8" fontSize={12} tickLine={false} axisLine={false} />
                <YAxis stroke="#94a3b8" fontSize={12} tickLine={false} axisLine={false} tickFormatter={(val) => `R$${val}`} />
                <Tooltip 
                  contentStyle={{ backgroundColor: '#0f172a', border: '1px solid #1e293b', borderRadius: '8px' }}
                  itemStyle={{ color: '#fff' }}
                  labelStyle={{ color: '#94a3b8' }}
                />
                <Bar dataKey="val" radius={[6, 6, 0, 0]}>
                  {chartData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={index % 2 === 0 ? '#4f46e5' : '#6366f1'} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </Card>

        <Card>
          <h3 className="text-lg font-bold text-white mb-6">Ações Rápidas</h3>
          <div className="space-y-3">
             <div className="p-4 rounded-xl border border-slate-800 bg-slate-800/30 hover:bg-slate-800 transition-colors flex items-center justify-between cursor-pointer group">
                <span className="text-sm text-slate-300 font-medium group-hover:text-white">Lançar folha rápida</span>
                <TrendingUp className="w-4 h-4 text-indigo-400" />
             </div>
             <div className="p-4 rounded-xl border border-slate-800 bg-slate-800/30 hover:bg-slate-800 transition-colors flex items-center justify-between cursor-pointer group">
                <span className="text-sm text-slate-300 font-medium group-hover:text-white">Relatório Anual</span>
                <FileText className="w-4 h-4 text-emerald-400" />
             </div>
             <div className="p-4 rounded-xl border border-slate-800 bg-slate-800/30 hover:bg-slate-800 transition-colors flex items-center justify-between cursor-pointer group">
                <span className="text-sm text-slate-300 font-medium group-hover:text-white">Atualizar Vales</span>
                <Users className="w-4 h-4 text-amber-400" />
             </div>
          </div>
        </Card>
      </div>
    </div>
