import React, { useState, useEffect } from 'react';
import { api } from '../services/api';
import { Employee } from '../services/types';
import { Card, Button, Input, Modal, Badge } from '../components/UI';
import { Plus, Search, Edit2, Trash2, MapPin, Briefcase } from 'lucide-react';

const Employees: React.FC = () => {
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingEmployee, setEditingEmployee] = useState<Employee | null>(null);
  const [isSaving, setIsSaving] = useState(false);

  const initialForm = {
    name: '', hireDate: '', company: '', address: '', city: '', state: '',
    fatherName: '', motherName: '', cpf: '', rg: '', ctps: '', pis: '',
    voterId: '', baseSalary: 0, functionBonus: 0
  };

  const [form, setForm] = useState(initialForm);

  useEffect(() => {
    loadEmployees();
  }, []);

  const loadEmployees = async () => {
    try {
      const data = await api.getEmployees();
      setEmployees(data);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSaving(true);
    try {
      if (editingEmployee) {
        await api.updateEmployee(editingEmployee.id, form);
      } else {
        await api.createEmployee(form);
      }
      setIsModalOpen(false);
      setEditingEmployee(null);
      setForm(initialForm);
      loadEmployees();
    } catch (err) {
      alert("Erro ao salvar funcionário");
    } finally {
      setIsSaving(false);
    }
  };

  const handleEdit = (emp: Employee) => {
    setEditingEmployee(emp);
    setForm({
      name: emp.name, hireDate: emp.hireDate, company: emp.company, address: emp.address,
      city: emp.city, state: emp.state, fatherName: emp.fatherName, motherName: emp.motherName,
      cpf: emp.cpf, rg: emp.rg, ctps: emp.ctps, pis: emp.pis, voterId: emp.voterId,
      baseSalary: emp.baseSalary, functionBonus: emp.functionBonus
    });
    setIsModalOpen(true);
  };

  const handleDelete = async (id: string) => {
    if (confirm("Tem certeza que deseja excluir este funcionário?")) {
      await api.deleteEmployee(id);
      loadEmployees();
    }
  };

  const filteredEmployees = employees.filter(e => 
    e.name.toLowerCase().includes(search.toLowerCase()) || e.cpf.includes(search)
  );

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h1 className="text-3xl font-bold text-white">Funcionários</h1>
          <p className="text-slate-400">Gerencie o quadro de colaboradores da empresa.</p>
        </div>
        <Button onClick={() => { setEditingEmployee(null); setForm(initialForm); setIsModalOpen(true); }}>
          <Plus className="w-4 h-4" />
          Novo Funcionário
        </Button>
      </div>

      <Card className="flex items-center gap-3 bg-slate-900/40 p-3">
        <Search className="w-5 h-5 text-slate-500 ml-2" />
        <input 
          type="text" 
          placeholder="Buscar por nome ou CPF..." 
          className="flex-1 bg-transparent border-none focus:ring-0 text-slate-200"
          value={search}
          onChange={(e) => setSearch(e.target.value)}
        />
      </Card>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {loading ? (
          [1,2,3].map(i => <div key={i} className="h-64 bg-slate-900 animate-pulse rounded-2xl border border-slate-800" />)
        ) : filteredEmployees.length === 0 ? (
          <div className="col-span-full py-20 text-center">
            <Users className="w-16 h-16 text-slate-800 mx-auto mb-4" />
            <p className="text-slate-500">Nenhum funcionário encontrado.</p>
          </div>
        ) : (
          filteredEmployees.map(emp => (
            <Card key={emp.id} className="group hover:border-indigo-500/50 transition-all">
              <div className="flex justify-between items-start mb-4">
                <div className="w-12 h-12 rounded-xl bg-indigo-500/10 flex items-center justify-center text-indigo-400 font-bold text-xl">
                  {emp.name.charAt(0)}
                </div>
                <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                  <button onClick={() => handleEdit(emp)} className="p-2 text-slate-400 hover:text-white hover:bg-slate-800 rounded-lg">
                    <Edit2 className="w-4 h-4" />
                  </button>
                  <button onClick={() => handleDelete(emp.id)} className="p-2 text-slate-400 hover:text-red-400 hover:bg-red-500/10 rounded-lg">
                    <Trash2 className="w-4 h-4" />
                  </button>
                </div>
              </div>

              <h3 className="text-lg font-bold text-white leading-tight mb-1">{emp.name}</h3>
              <p className="text-xs text-slate-500 mb-4 font-mono">{emp.cpf}</p>

              <div className="space-y-2 mb-6">
                <div className="flex items-center gap-2 text-sm text-slate-400">
                  <Briefcase className="w-4 h-4" />
                  <span>{emp.company}</span>
                </div>
                <div className="flex items-center gap-2 text-sm text-slate-400">
                  <MapPin className="w-4 h-4" />
                  <span>{emp.city}, {emp.state}</span>
                </div>
              </div>

              <div className="flex items-center justify-between pt-4 border-t border-slate-800">
                <div className="text-xs text-slate-500">
                  Salário Base
                  <p className="text-sm font-bold text-white">R$ {emp.baseSalary.toLocaleString('pt-BR')}</p>
                </div>
                <Badge variant="success">Ativo</Badge>
              </div>
            </Card>
          ))
        )}
      </div>

      <Modal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} title={editingEmployee ? "Editar Funcionário" : "Novo Funcionário"}>
        <form onSubmit={handleSubmit} className="space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <Input label="Nome Completo" value={form.name} onChange={e => setForm({...form, name: e.target.value})} required />
            <Input label="Data Admissão" type="date" value={form.hireDate} onChange={e => setForm({...form, hireDate: e.target.value})} required />
            <Input label="Empresa" value={form.company} onChange={e => setForm({...form, company: e.target.value})} required />
            <Input label="Cidade" value={form.city} onChange={e => setForm({...form, city: e.target.value})} required />
            <Input label="Estado" value={form.state} onChange={e => setForm({...form, state: e.target.value})} required />
            <Input label="CPF" value={form.cpf} onChange={e => setForm({...form, cpf: e.target.value})} required />
            <Input label="RG" value={form.rg} onChange={e => setForm({...form, rg: e.target.value})} required />
            <Input label="CTPS" value={form.ctps} onChange={e => setForm({...form, ctps: e.target.value})} />
            <Input label="Salário Base (R$)" type="number" step="0.01" value={form.baseSalary} onChange={e => setForm({...form, baseSalary: Number(e.target.value)})} required />
            <Input label="Acúmulo Função (R$)" type="number" step="0.01" value={form.functionBonus} onChange={e => setForm({...form, functionBonus: Number(e.target.value)})} />
          </div>

          <div className="pt-4 flex justify-end gap-3">
            <Button variant="secondary" onClick={() => setIsModalOpen(false)}>Cancelar</Button>
            <Button type="submit" isLoading={isSaving}>Salvar Alterações</Button>
          </div>
        </form>
      </Modal>
    </div>
  );
};

export default Employees;

