      setIsSaving(false);
    }
  };

  const handleEdit = (emp: Employee) => {
    setEditingEmployee(emp);
    setForm({
      name: emp.name, hireDate: emp.hireDate, company: emp.company, address: emp.address,
      city: emp.city, state: emp.state, fatherName: emp.fatherName, motherName: emp.motherName,
