import * as XLSX from 'xlsx';
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer,
  Cell
} from 'recharts';

const Dashboard: React.FC = () => {
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [launches, setLaunches] = useState<MonthlyLaunch[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [empData, launchData] = await Promise.all([
          api.getEmployees(),
          api.getLaunches()
        ]);
        setEmployees(empData);
        setLaunches(launchData);
      } catch (error) {
        console.error("Error fetching dashboard data", error);
      } finally {
        setLoading(false);
      }
    };
    fetchData();
  }, []);

  const totalPayroll = launches.reduce((acc, curr) => acc + curr.netSalary, 0);
  const avgSalary = employees.length > 0 ? employees.reduce((acc, curr) => acc + curr.baseSalary, 0) / employees.length : 0;

  const chartData = launches.slice(0, 6).reverse().map(l => ({
    name: l.employeeName.split(' ')[0],
    val: l.netSalary
  }));

  const exportToExcel = () => {
    if (launches.length === 0) return alert("Sem dados para exportar");

    // Cabeçalhos detalhados para o Excel
    const headers = [
      "ID Lançamento", 
      "Funcionário", 
      "Data Fechamento", 
      "Salário Base (R$)", 
      "Acúmulo Função (R$)", 
      "Prêmios (R$)",
      "Cesta Básica (R$)",
      "H.E. 100% (Qtd)",
      "H.E. 70% (Qtd)",
      "H.E. 50% (Qtd)",
      "V.T. (R$)",
      "Outros Rend. (R$)",
      "Adiantamentos (R$)", 
      "V. Refeição (R$)",
      "V. Alimentação (R$)",
      "Empréstimos (R$)",
      "C. Médico (R$)",
      "C. Dentário (R$)",
      "Total Proventos (R$)",
      "Total Descontos (R$)", 
      "Salário Líquido (R$)"
    ];

    const rows = launches.map(l => [
      l.id,
      l.employeeName,
      l.closingDate,
      l.baseSalary,
      l.functionBonus,
      l.premiumAmount || 0,
      l.basicBasket || 0,
      l.extraHours100 || 0,
      l.extraHours70 || 0,
      l.extraHours50 || 0,
      l.transportVoucherValue || 0,
      l.otherEarnings,
      l.advances,
      l.mealVoucher,
      l.foodVoucher,
      l.loans || 0,
      l.medicalConvenio,
      l.dentalConvenio,
      l.totalEarnings,
      l.totalDeductions,
      l.netSalary
    ]);

    // Criar a planilha usando SheetJS
    const worksheet = XLSX.utils.aoa_to_sheet([headers, ...rows]);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "Folha de Pagamento");

    // Ajustar largura das colunas automaticamente (opcional mas recomendado)
    const wscols = headers.map(h => ({ wch: h.length + 5 }));
    worksheet['!cols'] = wscols;

    // Gerar o download do arquivo .xlsx
    XLSX.writeFile(workbook, `folha_pagamento_${new Date().toISOString().split('T')[0]}.xlsx`);
  };

  if (loading) {
    return (
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 animate-pulse">
