  const handleQuickLaunch = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!quickLaunchForm.employeeId) return alert("Selecione um funcionário");

    setIsProcessing(true);
    try {
      const emp = employees.find(x => x.id === quickLaunchForm.employeeId)!;
      await api.createLaunch({
        employeeId: emp.id,
        employeeName: emp.name,
        closingDate: new Date().toISOString().split('T')[0],
        baseSalary: emp.baseSalary,
        functionBonus: emp.functionBonus,
        otherEarnings: quickLaunchForm.otherEarnings,
        premiumAmount: quickLaunchForm.premiumAmount,
        basicBasket: 0,
        extraHours100: 0,
        extraHours70: 0,
        extraHours50: 0,
        hasTransportVoucher: false,
        transportVoucherValue: 0,
        advances: 0,
        mealVoucher: emp.defaultMealVoucher || 0,
        foodVoucher: emp.defaultFoodVoucher || 0,
        medicalConvenio: 0,
        dentalConvenio: 0,
        pharmacyConvenio: 0,
        otherConvenios: 0,
        absences: quickLaunchForm.absences,
        loans: 0,
        otherDiscounts: '',
        notes: 'Lançamento via Ação Rápida'
      });
      setIsQuickLaunchOpen(false);
      setQuickLaunchForm({ employeeId: '', otherEarnings: 0, absences: 0, premiumAmount: 0 });
      fetchData();
    } catch (err) {
      alert("Erro no lançamento rápido");
    } finally {
      setIsProcessing(false);
    }
  };

  const handleBulkVoucherUpdate = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsProcessing(true);
    try {
      await api.bulkUpdateVouchers(bulkVoucherForm.meal, bulkVoucherForm.food);
      setIsBulkUpdateOpen(false);
      alert("Vales atualizados para todos os funcionários!");
      fetchData();
    } catch (err) {
      alert("Erro na atualização em lote");
    } finally {
      setIsProcessing(false);
    }
  };

  const exportAnnualReport = () => {
    if (launches.length === 0) return alert("Sem dados para o relatório");

    const year = new Date().getFullYear();
    const headers = ["Funcionário", "Janeiro", "Fevereiro", "Março", "Abril", "Maio", "Junho", "Julho", "Agosto", "Setembro", "Outubro", "Novembro", "Dezembro", "Total Anual"];

    // Agrupa lançamentos por funcionário
    const empMap: Record<string, number[]> = {};
    launches.forEach(l => {
      const date = new Date(l.closingDate);
      if (date.getFullYear() === year) {
        if (!empMap[l.employeeName]) empMap[l.employeeName] = new Array(12).fill(0);
        empMap[l.employeeName][date.getMonth()] += l.netSalary;
      }
    });

    const rows = Object.entries(empMap).map(([name, months]) => {
      const total = months.reduce((a, b) => a + b, 0);
      return [name, ...months, total];
    });

    const worksheet = XLSX.utils.aoa_to_sheet([headers, ...rows]);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, `Relatorio_${year}`);
    XLSX.writeFile(workbook, `Relatorio_Anual_RH_${year}.xlsx`);
  };

  const totalPayroll = launches.reduce((acc, curr) => acc + curr.netSalary, 0);
  const avgSalary = employees.length > 0 ? employees.reduce((acc, curr) => acc + curr.baseSalary, 0) / employees.length : 0;

  const chartData = launches.slice(0, 6).reverse().map(l => ({
    name: l.employeeName.split(' ')[0],
    val: l.netSalary
  }));

  if (loading) {
    return (
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 animate-pulse">
        {[1,2,3,4].map(i => (
          <div key={i} className="h-32 bg-slate-900 rounded-2xl border border-slate-800" />
        ))}
      </div>
    );
  }

  const kpis = [
    { label: 'Funcionários', value: employees.length, icon: Users, color: 'text-blue-400', bg: 'bg-blue-400/10' },
    { label: 'Total Folha (Líquido)', value: `R$ ${totalPayroll.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}`, icon: DollarSign, color: 'text-emerald-400', bg: 'bg-emerald-400/10' },
    { label: 'Salário Médio', value: `R$ ${avgSalary.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}`, icon: TrendingUp, color: 'text-indigo-400', bg: 'bg-indigo-400/10' },
    { label: 'Lançamentos', value: launches.length, icon: Receipt, color: 'text-amber-400', bg: 'bg-amber-400/10' },
  ];

  return (
    <div className="space-y-8">
      <div>
        <h1 className="text-3xl font-bold text-white mb-2">Visão Geral</h1>
        <p className="text-slate-400">Bem-vindo ao centro de controle de Recursos Humanos.</p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        {kpis.map((kpi, idx) => (
          <Card key={idx} className="flex flex-col gap-4 group transition-all hover:border-slate-700">
            <div className="flex items-center justify-between">
              <div className={`p-3 rounded-xl ${kpi.bg}`}>
                <kpi.icon className={`w-6 h-6 ${kpi.color}`} />
              </div>
              <Badge variant="info">Recente</Badge>
            </div>
            <div>
              <p className="text-sm text-slate-400 font-medium">{kpi.label}</p>
              <h3 className="text-2xl font-bold text-white mt-1">{kpi.value}</h3>
            </div>
          </Card>
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <Card className="lg:col-span-2">
          <div className="flex items-center justify-between mb-8">
            <h3 className="text-lg font-bold text-white">Últimos Pagamentos Líquidos</h3>
            <Button variant="secondary" onClick={() => XLSX.writeFile(XLSX.utils.book_new(), "dummy.xlsx")} className="text-xs">
              <Download className="w-4 h-4" />
              Exportar XLSX
            </Button>
          </div>
          <div className="h-[300px] w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={chartData}>
                <CartesianGrid strokeDasharray="3 3" stroke="#1e293b" vertical={false} />
                <XAxis dataKey="name" stroke="#94a3b8" fontSize={12} tickLine={false} axisLine={false} />
                <YAxis stroke="#94a3b8" fontSize={12} tickLine={false} axisLine={false} tickFormatter={(val) => `R$${val}`} />
                <Tooltip 
                  contentStyle={{ backgroundColor: '#0f172a', border: '1px solid #1e293b', borderRadius: '8px' }}
                  itemStyle={{ color: '#fff' }}
                  labelStyle={{ color: '#94a3b8' }}
                />
                <Bar dataKey="val" radius={[6, 6, 0, 0]}>
                  {chartData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={index % 2 === 0 ? '#4f46e5' : '#6366f1'} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </Card>

        <Card>
          <h3 className="text-lg font-bold text-white mb-6">Ações Rápidas</h3>
          <div className="space-y-3">
             <div onClick={() => setIsQuickLaunchOpen(true)} className="p-4 rounded-xl border border-slate-800 bg-slate-800/30 hover:bg-slate-800 transition-colors flex items-center justify-between cursor-pointer group">
                <span className="text-sm text-slate-300 font-medium group-hover:text-white">Lançar folha rápida</span>
                <Zap className="w-4 h-4 text-indigo-400" />
             </div>
             <div onClick={exportAnnualReport} className="p-4 rounded-xl border border-slate-800 bg-slate-800/30 hover:bg-slate-800 transition-colors flex items-center justify-between cursor-pointer group">
                <span className="text-sm text-slate-300 font-medium group-hover:text-white">Relatório Anual</span>
                <FileText className="w-4 h-4 text-emerald-400" />
             </div>
             <div onClick={() => setIsBulkUpdateOpen(true)} className="p-4 rounded-xl border border-slate-800 bg-slate-800/30 hover:bg-slate-800 transition-colors flex items-center justify-between cursor-pointer group">
                <span className="text-sm text-slate-300 font-medium group-hover:text-white">Atualizar Vales</span>
                <RefreshCw className="w-4 h-4 text-amber-400" />
             </div>
          </div>
        </Card>
      </div>

      {/* Modal: Lançamento Rápido */}
      <Modal isOpen={isQuickLaunchOpen} onClose={() => setIsQuickLaunchOpen(false)} title="Lançamento Rápido">
        <form onSubmit={handleQuickLaunch} className="space-y-4">
          <Select 
            label="Funcionário"
            value={quickLaunchForm.employeeId}
            onChange={e => setQuickLaunchForm({...quickLaunchForm, employeeId: e.target.value})}
            options={employees.map(emp => ({ value: emp.id, label: emp.name }))}
            required
          />
          <div className="grid grid-cols-2 gap-4">
            <Input label="Prêmios (R$)" type="number" step="0.01" value={quickLaunchForm.premiumAmount} onChange={e => setQuickLaunchForm({...quickLaunchForm, premiumAmount: Number(e.target.value)})} />
            <Input label="Rendimentos Extras (R$)" type="number" step="0.01" value={quickLaunchForm.otherEarnings} onChange={e => setQuickLaunchForm({...quickLaunchForm, otherEarnings: Number(e.target.value)})} />
          </div>
          <Input label="Faltas (Qtd Dias)" type="number" value={quickLaunchForm.absences} onChange={e => setQuickLaunchForm({...quickLaunchForm, absences: Number(e.target.value)})} />

          <div className="pt-4 border-t border-slate-800 flex justify-end gap-3">
             <Button variant="secondary" onClick={() => setIsQuickLaunchOpen(false)}>Cancelar</Button>
             <Button type="submit" isLoading={isProcessing}>Confirmar Lançamento</Button>
          </div>
        </form>
      </Modal>

      {/* Modal: Atualização em Lote */}
      <Modal isOpen={isBulkUpdateOpen} onClose={() => setIsBulkUpdateOpen(false)} title="Atualizar Benefícios em Lote">
        <form onSubmit={handleBulkVoucherUpdate} className="space-y-6">
          <div className="p-4 bg-amber-500/10 border border-amber-500/20 rounded-xl flex gap-3">
            <Calculator className="w-5 h-5 text-amber-400 shrink-0" />
            <p className="text-xs text-amber-200">Esta ação atualizará o valor padrão de VR/VA de TODOS os {employees.length} funcionários cadastrados.</p>
          </div>
          <div className="grid grid-cols-2 gap-4">
            <Input label="Novo Vale Refeição (R$)" type="number" step="0.01" value={bulkVoucherForm.meal} onChange={e => setBulkVoucherForm({...bulkVoucherForm, meal: Number(e.target.value)})} />
            <Input label="Novo Vale Alimentação (R$)" type="number" step="0.01" value={bulkVoucherForm.food} onChange={e => setBulkVoucherForm({...bulkVoucherForm, food: Number(e.target.value)})} />
          </div>
          <div className="pt-4 border-t border-slate-800 flex justify-end gap-3">
             <Button variant="secondary" onClick={() => setIsBulkUpdateOpen(false)}>Cancelar</Button>
             <Button type="submit" isLoading={isProcessing}>Atualizar Todos</Button>
          </div>
        </form>
      </Modal>
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect } from 'react';
import { api } from '../services/api';
import { Employee } from '../services/types';
import { Card, Button, Input, Modal, Badge, Select } from '../components/UI';
import { 
  Plus, 
  Search, 
  Edit2, 
  Trash2, 
  MapPin, 
  Briefcase, 
  Users, 
  User, 
  FileText, 
  DollarSign, 
  Phone,
  Save,
  Coffee
} from 'lucide-react';

const Employees: React.FC = () => {
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingEmployee, setEditingEmployee] = useState<Employee | null>(null);
  const [isSaving, setIsSaving] = useState(false);

  const initialForm = {
    name: '', 
    role: '',
    hireDate: '', 
    birthDate: '',
    company: '', 
    address: '', 
    phone: '',
    city: '', 
    state: '', 
    cep: '',
    fatherName: '', 
    motherName: '', 
    cpf: '', 
    rg: '', 
    ctps: '', 
    pis: '',
    voterId: '', 
    baseSalary: 0, 
    functionBonus: 0,
    defaultMealVoucher: 0,
    defaultFoodVoucher: 0
  };

  const [form, setForm] = useState(initialForm);

  useEffect(() => {
    loadEmployees();
  }, []);

  const loadEmployees = async () => {
    try {
      const data = await api.getEmployees();
      setEmployees(data);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSaving(true);
    try {
      if (editingEmployee) {
        await api.updateEmployee(editingEmployee.id, form);
      } else {
        await api.createEmployee(form);
      }
      setIsModalOpen(false);
      setEditingEmployee(null);
      setForm(initialForm);
      loadEmployees();
    } catch (err) {
      alert("Erro ao salvar funcionário");
    } finally {
      setIsSaving(false);
    }
  };

  const handleEdit = (emp: Employee) => {
    setEditingEmployee(emp);
    setForm({
      name: emp.name, 
      role: emp.role || '',
      hireDate: emp.hireDate, 
      birthDate: emp.birthDate || '',
      company: emp.company, 
      address: emp.address,
      phone: emp.phone || '',
      city: emp.city, 
      state: emp.state, 
      cep: emp.cep || '',
      fatherName: emp.fatherName, 
      motherName: emp.motherName,
      cpf: emp.cpf, 
      rg: emp.rg, 
      ctps: emp.ctps, 
      pis: emp.pis, 
      voterId: emp.voterId,
      baseSalary: emp.baseSalary, 
      functionBonus: emp.functionBonus,
      defaultMealVoucher: emp.defaultMealVoucher || 0,
      defaultFoodVoucher: emp.defaultFoodVoucher || 0
    });
    setIsModalOpen(true);
  };

  const handleDelete = async (id: string) => {
    if (confirm("Tem certeza que deseja excluir este funcionário?")) {
      await api.deleteEmployee(id);
      loadEmployees();
    }
  };

  const filteredEmployees = employees.filter(e => 
    e.name.toLowerCase().includes(search.toLowerCase()) || e.cpf.includes(search)
  );

  const SectionHeader = ({ icon: Icon, title }: { icon: any, title: string }) => (
    <div className="flex items-center gap-2 mb-4 mt-6 first:mt-0">
      <div className="p-1.5 bg-slate-800 rounded-lg">
        <Icon className="w-4 h-4 text-indigo-400" />
      </div>
      <h3 className="text-sm font-bold text-slate-200 uppercase tracking-wider">{title}</h3>
    </div>
  );

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h1 className="text-3xl font-bold text-white tracking-tight">Recursos Humanos</h1>
          <p className="text-slate-400">Cadastro e Gestão de Funcionários</p>
        </div>
        <Button onClick={() => { setEditingEmployee(null); setForm(initialForm); setIsModalOpen(true); }} className="px-6">
          <Plus className="w-5 h-5" />
          Novo Funcionário
        </Button>
      </div>

      <Card className="flex items-center gap-3 bg-slate-900/40 p-1 border-slate-800/50">
        <div className="flex items-center w-full bg-slate-800/50 rounded-xl px-3 py-1">
          <Search className="w-5 h-5 text-slate-500" />
          <input 
            type="text" 
            placeholder="Buscar por nome ou CPF..." 
            className="flex-1 bg-transparent border-none focus:ring-0 text-slate-200 py-3 ml-2 placeholder:text-slate-600"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
        </div>
      </Card>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {loading ? (
          [1,2,3].map(i => <div key={i} className="h-64 bg-slate-900 animate-pulse rounded-2xl border border-slate-800" />)
        ) : filteredEmployees.length === 0 ? (
          <div className="col-span-full py-20 text-center bg-slate-900/20 border border-dashed border-slate-800 rounded-3xl">
            <Users className="w-16 h-16 text-slate-800 mx-auto mb-4" />
            <p className="text-slate-500">Nenhum funcionário encontrado.</p>
          </div>
        ) : (
          filteredEmployees.map(emp => (
            <Card key={emp.id} className="group hover:border-indigo-500/50 transition-all border-slate-800">
              <div className="flex justify-between items-start mb-4">
                <div className="w-12 h-12 rounded-2xl bg-indigo-500/10 flex items-center justify-center text-indigo-400 font-bold text-xl border border-indigo-500/20">
                  {emp.name.charAt(0)}
                </div>
                <div className="flex gap-1">
                  <button onClick={() => handleEdit(emp)} className="p-2 text-slate-400 hover:text-white hover:bg-slate-800 rounded-lg transition-colors">
                    <Edit2 className="w-4 h-4" />
                  </button>
                  <button onClick={() => handleDelete(emp.id)} className="p-2 text-slate-400 hover:text-red-400 hover:bg-red-500/10 rounded-lg transition-colors">
                    <Trash2 className="w-4 h-4" />
                  </button>
                </div>
              </div>

              <h3 className="text-lg font-bold text-white leading-tight mb-1 truncate">{emp.name}</h3>
              <p className="text-xs text-slate-500 mb-4 font-mono">{emp.cpf}</p>

              <div className="space-y-2 mb-6">
                <div className="flex items-center gap-2 text-sm text-slate-400">
                  <Briefcase className="w-4 h-4" />
                  <span className="truncate">{emp.role || 'Cargo não definido'}</span>
                </div>
                <div className="flex items-center gap-2 text-sm text-slate-400">
                  <DollarSign className="w-4 h-4" />
                  <span className="truncate">R$ {(emp.baseSalary + emp.functionBonus).toLocaleString('pt-BR')}</span>
                </div>
              </div>

              <div className="flex items-center justify-between pt-4 border-t border-slate-800">
                <div className="text-[10px] text-slate-500 uppercase font-bold">
                  VR: R$ {emp.defaultMealVoucher} | VA: R$ {emp.defaultFoodVoucher}
                </div>
                <Badge variant="success">Ativo</Badge>
              </div>
            </Card>
          ))
        )}
      </div>

      <Modal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} title={editingEmployee ? "Editar Funcionário" : "Cadastro de Funcionários"}>
        <form onSubmit={handleSubmit} className="space-y-8">

          <div>
            <SectionHeader icon={Briefcase} title="Dados do Contrato" />
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <Select 
                label="EMPRESA CONTRATANTE" 
                value={form.company} 
                onChange={e => setForm({...form, company: e.target.value})} 
                options={[
                  { value: 'CAMPLUVAS', label: 'CAMPLUVAS' },
                  { value: 'LOCATEX', label: 'LOCATEX' }
                ]}
                placeholder="Selecione..."
                required
              />
              <Input label="DATA DE ADMISSÃO" type="date" value={form.hireDate} onChange={e => setForm({...form, hireDate: e.target.value})} required />
              <div className="md:col-span-2">
                <Input label="FUNÇÃO / CARGO" value={form.role} onChange={e => setForm({...form, role: e.target.value})} placeholder="Ex: Analista Financeiro" required />
              </div>
            </div>
          </div>

          <div>
            <SectionHeader icon={User} title="Identificação" />
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className="md:col-span-2">
                <Input label="NOME COMPLETO" value={form.name} onChange={e => setForm({...form, name: e.target.value})} placeholder="Digite o nome completo" required />
              </div>
              <Input label="NÚMERO CPF" value={form.cpf} onChange={e => setForm({...form, cpf: e.target.value})} placeholder="000.000.000-00" required />
              <Input label="REGISTRO GERAL (RG)" value={form.rg} onChange={e => setForm({...form, rg: e.target.value})} placeholder="00.000.000-0" required />
            </div>
          </div>

          <div>
            <SectionHeader icon={DollarSign} title="Remuneração Mensal" />
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <Input label="SALÁRIO BASE (RS)" type="number" step="0.01" value={form.baseSalary} onChange={e => setForm({...form, baseSalary: Number(e.target.value)})} required />
              <Input label="ACÚMULO DE FUNÇÃO (RS)" type="number" step="0.01" value={form.functionBonus} onChange={e => setForm({...form, functionBonus: Number(e.target.value)})} />
            </div>
          </div>

          {/* Novos campos para Vales Padrão */}
          <div>
            <SectionHeader icon={Coffee} title="Benefícios Padrão (Mensais)" />
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <Input label="VALE REFEIÇÃO PADRÃO (RS)" type="number" step="0.01" value={form.defaultMealVoucher} onChange={e => setForm({...form, defaultMealVoucher: Number(e.target.value)})} />
              <Input label="VALE ALIMENTAÇÃO PADRÃO (RS)" type="number" step="0.01" value={form.defaultFoodVoucher} onChange={e => setForm({...form, defaultFoodVoucher: Number(e.target.value)})} />
            </div>
          </div>

          <div>
            <SectionHeader icon={MapPin} title="Endereço e Contato" />
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              <div className="md:col-span-2">
                <Input label="ENDEREÇO" value={form.address} onChange={e => setForm({...form, address: e.target.value})} required />
              </div>
              <Input label="CIDADE" value={form.city} onChange={e => setForm({...form, city: e.target.value})} required />
              <Input label="UF" value={form.state} onChange={e => setForm({...form, state: e.target.value})} required />
              <Input label="CEP" value={form.cep} onChange={e => setForm({...form, cep: e.target.value})} />
            </div>
          </div>

          <div className="pt-8 border-t border-slate-800 flex justify-end">
            <Button type="submit" isLoading={isSaving} className="px-10 py-4 shadow-xl shadow-indigo-600/20">
              <Save className="w-5 h-5" />
              Finalizar Cadastro
            </Button>
          </div>
        </form>
      </Modal>
    </div>
  );
};

export default Employees;

