  const [isSaving, setIsSaving] = useState(false);
  const [cpfError, setCpfError] = useState(false);

  const initialForm = {
    name: '', 
    role: '',
    hireDate: '', 
    birthDate: '',
    company: '', 
    address: '', 
    phone: '',
    city: '', 
    state: '', 
    cep: '',
    fatherName: '', 
    motherName: '', 
    cpf: '', 
