  const [isSaving, setIsSaving] = useState(false);

  const initialForm = {
    employeeId: '',
    employeeName: '',
    date: new Date().toISOString().split('T')[0],
    baseSalary: 0,
    functionBonus: 0,
    otherEarnings: 0,
    reason: '',
    role: ''
  };

  const [form, setForm] = useState(initialForm);

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    setLoading(true);
    try {
      // Carrega funcionários primeiro para garantir a lista do formulário
      const empData = await api.getEmployees();
      setEmployees(empData || []);
    } catch (err) {
      console.error("Erro ao carregar funcionários:", err);
    }

    try {
      // Carrega evoluções. Se a tabela não existir (erro 404/400), o sistema continua
      const evData = await api.getSalaryEvolutions();
      setEvolutions(evData || []);
    } catch (err) {
      console.warn("Tabela de evolução salarial pode não estar criada ainda:", err);
    } finally {
      setLoading(false);
    }
  };

  const handleEmployeeChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const empId = e.target.value;
    const emp = employees.find(x => x.id === empId);
    if (emp) {
      setForm({
        ...form,
        employeeId: empId,
        employeeName: emp.name,
        baseSalary: emp.baseSalary,
        functionBonus: emp.functionBonus,
        role: emp.role
      });
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!form.employeeId) return alert("Selecione um funcionário");

    setIsSaving(true);
    try {
      // Apenas registra a evolução, sem alterar o cadastro original (conforme solicitado)
      await api.createSalaryEvolution(form);
      setIsModalOpen(false);
      setForm(initialForm);
      await loadData();
    } catch (err) {
      console.error(err);
      alert("Erro ao registrar evolução salarial. Verifique se a tabela existe no banco de dados.");
    } finally {
      setIsSaving(false);
    }
  };

  const handleDelete = async (id: string) => {
    if (confirm("Deseja excluir este registro de histórico?")) {
      await api.deleteSalaryEvolution(id);
      loadData();
    }
  };

  const exportToExcel = () => {
    if (evolutions.length === 0) return alert("Sem dados para exportar");

