      });
    } else {
      setForm({ ...form, employeeId: empId, employeeName: '' });
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    console.log("Iniciando submissão de evolução...", form);

    // Validação manual robusta
    if (!form.employeeId) return alert("Erro: Por favor, selecione um colaborador.");
    if (!form.role.trim()) return alert("Erro: O novo cargo/função é obrigatório.");
    if (!form.reason.trim()) return alert("Erro: O motivo da alteração é obrigatório.");
    if (!form.date) return alert("Erro: A data da alteração é obrigatória.");

    setIsSaving(true);
