          <p className="text-slate-400">Histórico de progressão e ajustes.</p>
        </div>
        <div className="flex gap-3 w-full sm:w-auto">
          <Button variant="secondary" onClick={exportToExcel} disabled={evolutions.length === 0} className="flex-1 sm:flex-none">
            <Download className="w-4 h-4" />
            Exportar XLSX
          </Button>
          <Button onClick={() => { setForm(initialForm); setIsModalOpen(true); }} className="flex-1 sm:flex-none">
            <Plus className="w-5 h-5" />
            Nova Evolução
          </Button>
        </div>
      </div>

      <Card className="flex items-center gap-3 bg-slate-900/40 p-1 border-slate-800/50">
