import { createClient } from '@supabase/supabase-js';
import { Employee, MonthlyLaunch, Advance, SalaryEvolution, HRService } from './types';

const SUPABASE_URL = 'https://dqhgabaqzeleazkzdrxj.supabase.co';
const SUPABASE_ANON_KEY = 'sb_publishable__R0MoyFcpNcmvos9YcKG0w_WhqC1G2-';

const supabase = createClient(SUPABASE_URL, SUPABASE_ANON_KEY);

const sanitizeData = (data: any) => {
  const clean: any = {};
  Object.keys(data).forEach(key => {
    const value = data[key];
    if (value === "" || value === undefined) {
      clean[key] = null;
    } else if (typeof value === 'number') {
      clean[key] = isNaN(value) ? 0 : value;
    } else {
      clean[key] = value;
    }
  });
  return clean;
};

export const supabaseService: HRService = {
  async validateLogin(email: string) {
    try {
      const { data, error } = await supabase
        .from('employees')
        .select('*')
        .eq('email', email.toLowerCase().trim())
        .maybeSingle();

      if (error) return null;
      return data as Employee | null;
    } catch (e) {
      return null;
    }
  },

  async getEmployees() {
    const { data, error } = await supabase
      .from('employees')
      .select('*')
      .order('name', { ascending: true });

    if (error) throw error;
    return data as Employee[];
  },

  async createEmployee(data) {
    const cleanData = sanitizeData(data);
    if (cleanData.email) cleanData.email = cleanData.email.toLowerCase().trim();

    const { data: newEmp, error } = await supabase
      .from('employees')
      .insert([cleanData])
      .select()
      .single();

    if (error) throw new Error(error.message);
    return newEmp as Employee;
  },

  async updateEmployee(id, data) {
    const cleanData = sanitizeData(data);
    const { data: updatedEmp, error } = await supabase
      .from('employees')
      .update(cleanData)
      .eq('id', id)
      .select()
      .single();

    if (error) throw error;
    return updatedEmp as Employee;
  },

  async deleteEmployee(id) {
    const { error } = await supabase.from('employees').delete().eq('id', id);
    if (error) throw error;
  },

  async getLaunches() {
    const { data, error } = await supabase
      .from('launches')
      .select('*')
      .order('closingDate', { ascending: false });

    if (error) throw error;
    return data as MonthlyLaunch[];
  },

  async createLaunch(data) {
    const cleanData = sanitizeData(data);
    const totalEarnings = Number(cleanData.baseSalary || 0) + 
                          Number(cleanData.functionBonus || 0) + 
                          Number(cleanData.otherEarnings || 0) + 
                          Number(cleanData.premiumAmount || 0) + 
                          Number(cleanData.basicBasket || 0) +
                          Number(cleanData.mealVoucher || 0) +
                          Number(cleanData.foodVoucher || 0);

    const totalDeductions = Number(cleanData.advances || 0) + 
                            Number(cleanData.medicalConvenio || 0) + 
                            Number(cleanData.dentalConvenio || 0) + 
                            Number(cleanData.pharmacyConvenio || 0) + 
                            Number(cleanData.otherConvenios || 0) + 
                            Number(cleanData.transportVoucherValue || 0) +
                            Number(cleanData.loans || 0) +
                            Number(cleanData.absences || 0);

    const netSalary = totalEarnings - totalDeductions;

    const { data: newLaunch, error } = await supabase
      .from('launches')
      .insert([{ ...cleanData, totalEarnings, totalDeductions, netSalary }])
      .select()
      .single();

    if (error) throw error;
    return newLaunch as MonthlyLaunch;
  },

  async updateLaunch(id, data) {
    const { data: current } = await supabase.from('launches').select('*').eq('id', id).single();
    if (!current) throw new Error('Lançamento não encontrado');

    const cleanData = sanitizeData(data);
    const updated = { ...current, ...cleanData };

    updated.totalEarnings = Number(updated.baseSalary) + Number(updated.functionBonus) + 
                            Number(updated.otherEarnings) + Number(updated.premiumAmount) + 
                            Number(updated.basicBasket) + Number(updated.mealVoucher) + 
                            Number(updated.foodVoucher);

    updated.totalDeductions = Number(updated.advances) + Number(updated.medicalConvenio) + 
                            Number(updated.dentalConvenio) + Number(updated.pharmacyConvenio) + 
                            Number(updated.otherConvenios) + Number(updated.transportVoucherValue) + 
                            Number(updated.loans) + Number(updated.absences);

    updated.netSalary = updated.totalEarnings - updated.totalDeductions;

    const { data: updatedLaunch, error } = await supabase
      .from('launches')
      .update(updated)
      .eq('id', id)
      .select()
      .single();

    if (error) throw error;
    return updatedLaunch as MonthlyLaunch;
  },

  async deleteLaunch(id) {
    const { error } = await supabase.from('launches').delete().eq('id', id);
    if (error) throw error;
  },

  async getAdvancesByPeriod(period) {
    const { data, error } = await supabase.from('advances').select('*').eq('period', period);
    if (error) throw error;
    return data as Advance[];
  },

  async saveAdvances(newAdvances) {
    if (newAdvances.length === 0) return;
    const period = newAdvances[0].period;
    await supabase.from('advances').delete().eq('period', period);
    const cleanAdvances = newAdvances.map(a => sanitizeData(a));
    const { error } = await supabase.from('advances').insert(cleanAdvances);
    if (error) throw error;
  },

  async getSalaryEvolutions() {
    const { data, error } = await supabase
      .from('salary_evolution')
      .select('*')
      .order('date', { ascending: false });

    if (error) {
      // Códigos de erro Postgres para tabela não encontrada
      if (error.code === '42P01' || error.message.includes('cache') || error.message.includes('not found')) {
        const customError: any = new Error("Tabela 'salary_evolution' não encontrada no banco de dados.");
        customError.code = 'TABLE_MISSING';
        throw customError;
      }
      return [];
    }
    return data as SalaryEvolution[];
  },

  async createSalaryEvolution(data) {
    const cleanData = sanitizeData(data);

    const { data: newEv, error } = await supabase
      .from('salary_evolution')
      .insert([cleanData])
      .select();

    if (error) {
      if (error.code === '42P01' || error.message.includes('cache')) {
        const customError: any = new Error("Erro: A tabela 'salary_evolution' não existe. Por favor, execute o script SQL.");
        customError.code = 'TABLE_MISSING';
        throw customError;
      }
      throw new Error(error.message);
    }

    return (newEv ? newEv[0] : null) as SalaryEvolution;
  },

  async deleteSalaryEvolution(id) {
    const { error } = await supabase.from('salary_evolution').delete().eq('id', id);
    if (error) throw error;
  },

  async bulkUpdateVouchers(meal, food) {
    const { error } = await supabase
      .from('employees')
      .update({ defaultMealVoucher: meal, defaultFoodVoucher: food })
      .not('id', 'is', null);
    if (error) throw error;
  }
};

import React, { useState, useEffect } from 'react';
import { api } from '../services/api';
import { Employee, SalaryEvolution as ISalaryEvolution } from '../services/types';
import { Card, Button, Input, Modal, Select, Badge } from '../components/UI';
import { 
  TrendingUp, 
  Plus, 
  Search, 
  Trash2, 
  Calendar, 
  DollarSign, 
  Briefcase, 
  History,
  Download,
  ArrowRight,
  FileText,
  AlertCircle,
  Database,
  Copy,
  CheckCircle2
} from 'lucide-react';
import * as XLSX from 'xlsx';

const SalaryEvolution: React.FC = () => {
  const [evolutions, setEvolutions] = useState<ISalaryEvolution[]>([]);
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [missingTable, setMissingTable] = useState(false);

  const initialForm = {
    employeeId: '',
    employeeName: '',
    date: new Date().toISOString().split('T')[0],
    baseSalary: 0,
    functionBonus: 0,
    otherEarnings: 0,
    reason: '',
    role: ''
  };

  const [form, setForm] = useState(initialForm);

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    setLoading(true);
    setMissingTable(false);
    try {
      const empData = await api.getEmployees();
      setEmployees(empData || []);

      const evData = await api.getSalaryEvolutions();
      setEvolutions(evData || []);
    } catch (err: any) {
      if (err.code === 'TABLE_MISSING' || err.message.includes('cache') || err.message.includes('42P01')) {
        setMissingTable(true);
      } else {
        console.error("Erro ao carregar evoluções:", err);
      }
    } finally {
      setLoading(false);
    }
  };

  const handleEmployeeChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const empId = e.target.value;
    const emp = employees.find(x => x.id === empId);
    if (emp) {
      setForm({
        ...form,
        employeeId: empId,
        employeeName: emp.name,
        baseSalary: Number(emp.baseSalary) || 0,
        functionBonus: Number(emp.functionBonus) || 0,
        role: emp.role || ''
      });
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!form.employeeId) return alert("Selecione um funcionário.");
    if (!form.role.trim()) return alert("O cargo é obrigatório.");
    if (!form.reason.trim()) return alert("O motivo é obrigatório.");

    setIsSaving(true);
    try {
      const payload = {
        employeeId: form.employeeId,
        employeeName: form.employeeName,
        date: form.date,
        baseSalary: Number(form.baseSalary),
        functionBonus: Number(form.functionBonus),
        otherEarnings: Number(form.otherEarnings),
        reason: form.reason,
        role: form.role
      };

      await api.createSalaryEvolution(payload);

      alert("Sucesso! Evolução salarial registrada.");
      setIsModalOpen(false);
      setForm(initialForm);
      await loadData();
    } catch (err: any) {
      console.error("Erro ao registrar evolução:", err);
      if (err.code === 'TABLE_MISSING' || err.message.includes('cache')) {
        setMissingTable(true);
        alert("A tabela de evolução não existe no seu banco de dados. Siga as instruções na tela.");
      } else {
        alert(err.message || "Erro desconhecido ao salvar.");
      }
    } finally {
      setIsSaving(false);
    }
  };

  const handleDelete = async (id: string) => {
